// =============================================================
// icon_images.js
// 資源系MarkIcon(Metal / Obsidian / Crystal / Pearl)の実物画像。
// ゲーム内ではアイテムのテクスチャ画像そのものが使われており、
// 単色SVGでは再現できないため、ユーザーがゲーム内で撮影した
// スクリーンショットから切り抜いて背景を透過した画像を
// data URIとして埋め込んでいる(撮影: れしあ)。
// waypoint_icon.js がこのマップにIDがある定義を画像で描画する。
// =============================================================

/** @type {Record<string, string>} MarkIcon定義ID -> data URI */
export const ICON_IMAGES = {
  Metal: 'data:image/webp;base64,',
  Obsidian: 'data:image/webp;base64,',
  Crystal: 'data:image/webp;base64,',
  Pearl: 'data:image/webp;base64,',
};
